import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        n = int(next(it))
        L = int(next(it))
        R = int(next(it))
        s = [int(next(it)) for _ in range(n)]

        # Kadane 求最小非空子段和
        min_sum = None
        cur = 0
        for x in s:
            if L <= x <= R:
                # 将 x 移到区间外的最近端点
                b = min(x - L + 1, R - x + 1)
            else:
                b = 0
            c = b - 1
            # cur 表示以当前元素结尾的最小子段和
            if cur + c < c:
                cur = cur + c
            else:
                cur = c
            if min_sum is None or cur < min_sum:
                min_sum = cur
        ans = n + min_sum
        out_lines.append(str(ans))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
